const runId = $('Run Id').first().json.run_id;
const expected = $('Load Cases').all().length;
const rows = $input.all().map(i => i.json).filter(r => r.run_id === runId);
const slugs = {};
for (const c of $('Load Cases').all()) slugs[c.json.id] = c.json.slug;
// Load Results' getAll() overlaps pages while sub-workflows are still writing,
// so it can emit the same row multiple times. Dedupe by case_id.
const seen = new Set();
const unique = [];
for (const r of rows) {
  if (!r.case_id || seen.has(r.case_id)) continue;
  seen.add(r.case_id);
  unique.push(r);
}
const counts = { pass: 0, fail: 0, error: 0 };
const cases = unique.map(r => {
  counts[r.status] = (counts[r.status] || 0) + 1;
  return { slug: slugs[r.case_id] || r.case_id, status: r.status, called_tools: r.called_tools, assertion_results: r.assertion_results };
});
cases.sort((a, b) => (a.slug < b.slug ? -1 : 1));
const poll = ($runIndex || 0) + 1;
return [{ json: {
  run_id: runId,
  expected: expected,
  landed: unique.length,
  polls: poll,
  complete: unique.length >= expected,
  timeout: poll >= 20,
  pass: counts.pass,
  fail: counts.fail,
  error: counts.error,
  cases: cases
} }];

// n8n Code node — "Run Once for All Items"
// Input:  one or more items containing run objects (or arrays of them)
// Output: a single item with the whole report as one markdown string

const CONFIG = {
  useEmoji: true,       // ✅ / ❌ / 💥 / ⏭️ vs plain text labels
};

const STATUS_ICON = { pass: '✅', fail: '❌', error: '💥', skip: '⏭️' };
const STATUS_RANK = { fail: 0, error: 1, pass: 2, skip: 3 };

const icon = (s) => (CONFIG.useEmoji ? `${STATUS_ICON[s] || '•'} ${s}` : s);
const rankOf = (s) => (Object.prototype.hasOwnProperty.call(STATUS_RANK, String(s).toLowerCase()) ? STATUS_RANK[String(s).toLowerCase()] : 4);

// called_tools arrives as a JSON-encoded string, but tolerate arrays/null too.
function parseTools(raw) {
  if (Array.isArray(raw)) return raw.map(String);
  if (typeof raw !== 'string' || raw.trim() === '') return [];
  try {
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed.map(String) : [String(parsed)];
  } catch {
    return [raw];
  }
}

// assertion_results arrives as a JSON-encoded string (legacy rows) or a real array.
function parseAssertions(raw) {
  if (Array.isArray(raw)) return raw;
  if (typeof raw !== 'string' || raw.trim() === '') return [];
  try {
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [parsed];
  } catch {
    return [];
  }
}

// Pipes and newlines break markdown tables.
const cell = (t) => String(t).replace(/\|/g, '\\|').replace(/\n+/g, ' ');

function table(headers, rows) {
  const lines = [
    `| ${headers.join(' | ')} |`,
    `| ${headers.map(() => '---').join(' | ')} |`,
  ];
  for (const row of rows) lines.push(`| ${row.map(cell).join(' | ')} |`);
  return lines.join('\n');
}

const pct = (part, total) => (total ? `${((part / total) * 100).toFixed(1)}%` : 'n/a');

// Runs may arrive one-per-item, all nested in one item, or under a wrapper key.
function collectRuns(items) {
  const runs = [];
  const push = (v) => {
    if (Array.isArray(v)) v.forEach(push);
    else if (v && typeof v === 'object' && Array.isArray(v.cases)) runs.push(v);
  };
  for (const item of items) {
    const json = item.json ?? item;
    if (Array.isArray(json) || (json && Array.isArray(json.cases))) {
      push(json);
    } else if (json && typeof json === 'object') {
      // e.g. { data: [...] } or { runs: [...] } from an upstream HTTP node
      Object.values(json).forEach(push);
    }
  }
  return runs;
}

function renderRun(run, index, totalRuns) {
  const cases = Array.isArray(run.cases) ? run.cases : [];
  const out = [];

  // Count from the cases themselves rather than trusting the summary fields.
  const counts = {};
  for (const c of cases) {
    const status = String(c.status || 'unknown').toLowerCase();
    counts[status] = (counts[status] || 0) + 1;
  }
  const passed = counts.pass || 0;

  out.push(totalRuns > 1 ? `## Run ${index + 1}: \`${run.run_id}\`` : `## \`${run.run_id}\``, '');
  out.push(
    `**${run.complete ? 'Complete' : 'Incomplete'}** · ${run.landed}/${run.expected} cases landed · ` +
      `${run.polls} poll${run.polls === 1 ? '' : 's'} · **${pct(passed, cases.length)} pass rate**`,
    ''
  );

  if (!cases.length) {
    out.push('No cases recorded for this run.', '');
    return { markdown: out.join('\n'), counts, total: cases.length, passed };
  }

  const order = ['pass', 'fail', 'error', 'skip'];
  const rank = (s) => (order.indexOf(s) === -1 ? order.length : order.indexOf(s));
  out.push(
    table(
      ['Result', 'Count', 'Share'],
      Object.keys(counts)
        .sort((a, b) => rank(a) - rank(b) || a.localeCompare(b))
        .map((s) => [icon(s), counts[s], pct(counts[s], cases.length)])
    ),
    ''
  );

  // Discrepancies between the reported summary and the actual cases.
  const warnings = [];
  for (const key of ['pass', 'fail', 'error']) {
    const reported = run[key];
    const actual = counts[key] || 0;
    if (typeof reported === 'number' && reported !== actual) {
      warnings.push(`\`${key}\` reported as ${reported}, counted ${actual} in cases`);
    }
  }
  if (typeof run.landed === 'number' && run.landed !== cases.length) {
    warnings.push(`\`landed\` reported as ${run.landed}, but ${cases.length} cases present`);
  }
  if (typeof run.expected === 'number' && run.expected !== run.landed) {
    warnings.push(`${run.expected - run.landed} case(s) never landed`);
  }
  if (warnings.length) {
    out.push('> [!WARNING]');
    out.push('> Summary counts do not match the case list:');
    warnings.forEach((w) => out.push(`> - ${w}`));
    out.push('');
  }

  // Cases, sorted with failures first.
  out.push('### Cases', '');
  out.push(
    table(
      ['Case', 'Status', 'Tools called'],
      [...cases]
        .sort(
          (a, b) =>
            rankOf(a.status) - rankOf(b.status) ||
            String(a.slug).localeCompare(String(b.slug))
        )
        .map((c) => {
          const tools = parseTools(c.called_tools);
          return [
            `\`${c.slug}\``,
            icon(String(c.status || 'unknown').toLowerCase()),
            tools.length ? tools.map((t) => `\`${t}\``).join(', ') : '—',
          ];
        })
    ),
    ''
  );

  // Failing assertion detail, so a red row is actionable without opening the DB.
  const failing = cases.filter((c) => ['fail', 'error'].includes(String(c.status || '').toLowerCase()));
  const failingLines = [];
  for (const c of failing) {
    const failed = parseAssertions(c.assertion_results).filter((a) => a && a.pass === false);
    if (!failed.length) continue;
    failingLines.push(
      `- \`${c.slug}\`: ` +
        failed
          .map((a) => `\`${a.type}${a.tool || a.value ? ' ' + (a.tool || a.value) : ''}\``)
          .join(', ')
    );
  }
  if (failingLines.length) {
    out.push('#### Failing assertions', '', ...failingLines, '');
  }

  return { markdown: out.join('\n'), counts, total: cases.length, passed };
}

// --- main -------------------------------------------------------------------

const runs = collectRuns($input.all());

if (!runs.length) {
  throw new Error('No run objects found in input — expected objects with a `cases` array.');
}

// This workflow IS the dispatcher, so the current execution is the dispatcher run.
const baseUrl = $vars.instance_url || 'https://darwin-staging.app.n8n.cloud';
const wfId = ($workflow && $workflow.id) || 'xs39cdr3D4dEtLOX';
const executionUrl = `${baseUrl}/workflow/${wfId}/executions/${$execution.id}`;

const generatedAt = new Date().toISOString();
const rendered = runs.map((run, i) => renderRun(run, i, runs.length));

const totalCases = rendered.reduce((n, r) => n + r.total, 0);
const totalPass = rendered.reduce((n, r) => n + r.passed, 0);
const totalFailing = rendered.reduce(
  (n, r) => n + (r.counts.fail || 0) + (r.counts.error || 0),
  0
);

const parts = [];
if (runs.length > 1) {
  parts.push(
    `${runs.length} runs · ${totalCases} cases · ${pct(totalPass, totalCases)} overall pass rate`,
    ''
  );
}
rendered.forEach((r) => parts.push(r.markdown));
parts.push(`_Generated ${generatedAt}_ · [Dispatcher execution](${executionUrl})`);

const markdown = parts.join('\n').replace(/\n{3,}/g, '\n\n').trimEnd() + '\n';

// Single item out. Extra fields are there so downstream IF/Switch nodes don't
// have to re-parse the markdown to decide whether to alert.
return [
  {
    json: {
      markdown,
      generated_at: generatedAt,
      execution_url: executionUrl,
      run_ids: runs.map((r) => r.run_id),
      run_count: runs.length,
      total_cases: totalCases,
      total_pass: totalPass,
      total_failing: totalFailing,
      pass_rate: totalCases ? Number(((totalPass / totalCases) * 100).toFixed(1)) : null,
      all_passed: totalFailing === 0,
      char_count: markdown.length,
    },
  },
];

// Build Slack Block Kit markdown blocks from the Summary node's markdown output.
// Splits long text across multiple mrkdwn blocks (3,000-char limit each),
// up to ~90KB total serialized JSON payload to stay within Slack API limits.
// Splits on newlines where possible. Ported from the "Slack" workflow (9UJFDlOnoxSzFCS1).

const PER_BLOCK = 2900;  // leave margin under Slack's 3000-char limit
const MAX_BLOCKS = 50;   // hard cap: Slack max 50 blocks
const MAX_PAYLOAD_BYTES = 90000;  // ~90KB budget for serialized { blocks: [...] }
const TRUNCATION_NOTE = '\n\n_… (truncated: response too long for a single Slack message)_';

let text = $json.markdown ?? '';
const fullText = text;  // preserve original for downstream use

// --- Helper: estimate serialized size of a blocks array ---
function estimatePayloadSize(blocksArr) {
  // Serialize just the blocks array; the outer { "blocks": [...] } wrapper adds ~15 chars
  return JSON.stringify(blocksArr).length + 20;
}

// --- Split text into chunks ---
function splitIntoChunks(str, chunkSize, maxBlocks, maxBytes) {
  const chunks = [];
  const trialBlocks = [];

  while (str.length > 0 && chunks.length < maxBlocks) {
    if (str.length <= chunkSize) {
      chunks.push(str);
      trialBlocks.push({ type: 'markdown', text: str });
      if (estimatePayloadSize(trialBlocks) > maxBytes) {
        const removed = chunks.pop();
        trialBlocks.pop();
        const remaining = maxBytes - estimatePayloadSize(trialBlocks);
        const maxTextLen = Math.max(0, remaining - 60);
        if (maxTextLen > 50) {
          chunks.push(removed.slice(0, maxTextLen) + TRUNCATION_NOTE);
        }
      }
      break;
    }

    // Try to find last newline within the chunk boundary
    const sliceTarget = str.slice(0, chunkSize);
    const lastNewline = sliceTarget.lastIndexOf('\n');
    let chunk;
    if (lastNewline > chunkSize - 500) {
      chunk = str.slice(0, lastNewline);
      str = str.slice(lastNewline + 1);
    } else {
      chunk = sliceTarget;
      str = str.slice(chunkSize);
    }

    const tentativeBlocks = [...trialBlocks, { type: 'markdown', text: chunk }];
    if (estimatePayloadSize(tentativeBlocks) > maxBytes) {
      const remaining = maxBytes - estimatePayloadSize(trialBlocks);
      const maxTextLen = Math.max(0, remaining - 60);
      if (maxTextLen > 50) {
        chunks.push(chunk.slice(0, maxTextLen) + TRUNCATION_NOTE);
      }
      break;
    }

    chunks.push(chunk);
    trialBlocks.push({ type: 'markdown', text: chunk });
  }

  if (str.length > 0 && chunks.length === maxBlocks) {
    chunks[chunks.length - 1] = chunks[chunks.length - 1].replace(/\n*$/, '') + TRUNCATION_NOTE;
  }

  return chunks;
}

const chunks = splitIntoChunks(text, PER_BLOCK, MAX_BLOCKS, MAX_PAYLOAD_BYTES);
const blocks = chunks.map(t => ({ type: 'markdown', text: t }));
const content = { blocks };

return [{ json: { blocksJson: JSON.stringify(content), output: fullText } }];

// Group the formatted blocks into message-sized chunks so no single Slack
// message exceeds Slack's cumulative block-text limit (~13k chars, undocumented —
// see slackapi/bolt-js#2509). Emits one item per message; Send a message then posts
// one message per item. Ported from the "Slack" workflow (9UJFDlOnoxSzFCS1).
const MSG_BUDGET = 8000; // chars of block text per message, safe margin under ~13k

const blocksJson = $('format').first().json.blocksJson;

let blocks;
try {
  blocks = JSON.parse(blocksJson).blocks;
  if (!Array.isArray(blocks) || blocks.length === 0) throw new Error('no blocks');
} catch (e) {
  // Fall back to previous single-message behaviour if parsing fails
  return [{ json: { blocksJson, part: 1, totalParts: 1 } }];
}

const messages = [];
let current = [];
let currentLen = 0;

for (const block of blocks) {
  const len = (block.text || '').length;
  if (current.length > 0 && currentLen + len > MSG_BUDGET) {
    messages.push(current);
    current = [];
    currentLen = 0;
  }
  current.push(block);
  currentLen += len;
}
if (current.length > 0) messages.push(current);

return messages.map((msgBlocks, i) => ({
  json: {
    blocksJson: JSON.stringify({ blocks: msgBlocks }),
    part: i + 1,
    totalParts: messages.length,
  },
}));
